                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                        item.EDID = StringBinaryTranslation.Instance.Parse(
                            reader: frame.SpawnWithLength(contentLength),
                            stringBinaryType: StringBinaryType.NullTerminate,
                            parseWhole: true);
                        return new ParseResult((int)Component_FieldIndex.EDID, nextRecordType);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(nextRecordType) ?? 0)
                        {
                            case 0:
                                return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                                    item: item,
                                    frame: frame,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    nextRecordType: nextRecordType,
                                    contentLength: contentLength,
                                    translationParams: translationParams.WithNoConverter());
                            case 1:
                                frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                                item.EDID = StringBinaryTranslation.Instance.Parse(
                                    reader: frame.SpawnWithLength(contentLength),
                                    stringBinaryType: StringBinaryType.NullTerminate,
                                    parseWhole: true);
                                return new ParseResult((int)Component_FieldIndex.EDID, nextRecordType);
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.OBND:
                {
                    item.ObjectBounds = Mutagen.Bethesda.Fallout76.ObjectBounds.CreateFromBinary(frame: frame);
                    return (int)Component_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.FULL:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FULL = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        eager: true,
                        source: StringsSource.Normal,
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)Component_FieldIndex.FULL;
                }
                case RecordTypeInts.CUSD:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.CraftingSound.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Component_FieldIndex.CraftingSound;
                }
                case RecordTypeInts.VCRY:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.ValueCurrency.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Component_FieldIndex.ValueCurrency;
                }
                case RecordTypeInts.DATA:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.DATA = frame.ReadUInt32();
                    return (int)Component_FieldIndex.DATA;
                }
                case RecordTypeInts.MNAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.ScrapItem.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Component_FieldIndex.ScrapItem;
                }
                case RecordTypeInts.GNAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.ModScrapScalar.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Component_FieldIndex.ModScrapScalar;
                }
                case RecordTypeInts.CVPA:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.CVPA = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Component_FieldIndex.CVPA;
                }
                case RecordTypeInts.ILAC:
                {
                    item.ILAC = Mutagen.Bethesda.Fallout76.ComponentILACData.CreateFromBinary(frame: frame);
                    return (int)Component_FieldIndex.ILAC;
